<?php require 'config.php';$u=need('operator','admin');
if($_POST){chk();$a=$_POST['a'];
 if($a=='bus'&&trim($_POST['reg'])!==''){q('INSERT INTO buses(reg_number,operator,operator_id,capacity,driver_name,license_no,driver_id_no,kind,license_doc) VALUES(?,?,?,?,?,?,?,?,?)',[trim($_POST['reg']),$u['name'],$u['id'],max(10,min(60,(int)$_POST['cap'])),trim($_POST['driver']),trim($_POST['lic']),trim($_POST['did']),$_POST['kind']=='local'?'local':'intercity',upload_private($_FILES['doc']??[])]);q('UPDATE buses SET gps_key=? WHERE id=?',[bin2hex(random_bytes(16)),$pdo->lastInsertId()]);flash('Bus submitted. It appears in search after admin approval.');}
 if($a=='trip')q("INSERT INTO trips(route_id,bus_id,depart_date,depart_time) SELECT ?,id,?,? FROM buses WHERE id=? AND status='approved' AND (operator_id=? OR ?='admin')",[(int)$_POST['route'],$_POST['date'],$_POST['time'],(int)$_POST['bus'],$u['id'],$u['role']]);
 if($a=='trip'&&!empty($_POST['daily']))q("INSERT INTO schedules(route_id,bus_id,depart_time) SELECT ?,id,? FROM buses WHERE id=? AND status='approved' AND (operator_id=? OR ?='admin')",[(int)$_POST['route'],$_POST['time'],(int)$_POST['bus'],$u['id'],$u['role']]);
 if($a=='status'&&in_array($_POST['v'],['scheduled','running','delayed','completed','cancelled'])){$n=q('UPDATE trips t JOIN buses b ON b.id=t.bus_id SET t.status=? WHERE t.id=? AND (b.operator_id=? OR ?="admin")',[$_POST['v'],(int)$_POST['id'],$u['id'],$u['role']])->rowCount();if($n&&$_POST['v']=='cancelled')cancel_trip((int)$_POST['id']);}
 header('Location: operator.php');exit;}
$buses=q('SELECT * FROM buses WHERE operator_id=? OR ?="admin" ORDER BY id DESC',[$u['id'],$u['role']])->fetchAll();$routes=q('SELECT * FROM routes')->fetchAll();
$trips=q('SELECT t.*,r.from_city,r.to_city,b.reg_number FROM trips t JOIN routes r ON r.id=t.route_id JOIN buses b ON b.id=t.bus_id WHERE b.operator_id=? OR ?="admin" ORDER BY depart_date DESC',[$u['id'],$u['role']])->fetchAll();
head('Operator');?><h2>Operator dashboard</h2>
<form method="post" enctype="multipart/form-data" class="card"><?=tok()?><input type="hidden" name="a" value="bus"><h3>Register a bus</h3>
<label>Registration number<input name="reg" required></label><label>Seats<input type="number" name="cap" value="40" min="10" max="60"></label><label>Driver name<input name="driver" required></label><label>Licence number<input name="lic" required></label><label>Driver ID number<input name="did" required></label><label>Bus type<select name="kind"><option value="intercity">Long-distance</option><option value="local">Local</option></select></label>
<label>Licence copy (JPG, PNG or PDF, max 2 MB)<input type="file" name="doc" accept=".jpg,.jpeg,.png,.pdf"></label><button class="btn">Submit for approval</button></form>
<h3>My buses</h3><?php foreach($buses as $b)echo '<div class="card trip"><span>'.e($b['reg_number']).' · '.e($b['driver_name']).'<br><small class="muted">GPS key: '.e($b['gps_key']).'</small></span><span class="pill '.($b['status']=='approved'?'verified':'pending').'">'.e($b['status']).'</span></div>';?>
<form method="post" class="card row"><?=tok()?><input type="hidden" name="a" value="trip"><label>Bus<select name="bus"><?php foreach($buses as $b)if($b['status']=='approved')echo '<option value="'.$b['id'].'">'.e($b['reg_number']).'</option>';?></select></label>
<label>Route<select name="route"><?php foreach($routes as $r)echo '<option value="'.$r['id'].'">'.e($r['from_city'].' to '.$r['to_city'].' ('.$r['type'].')').'</option>';?></select></label><label>Date<input type="date" name="date" required></label><label>Time<input type="time" name="time" required></label><label><input type="checkbox" name="daily" value="1" style="display:inline;width:auto"> Repeat daily</label><button class="btn">Add trip</button></form>
<div class="card"><h3>Use this phone as the bus GPS</h3><p class="muted">Keep this page open on the driver's phone. A GPS device can also POST bus, key, lat, lng to gps_update.php.</p><label>Bus<select id="gb"><?php foreach($buses as $b)if($b['status']=='approved')echo '<option value="'.$b['id'].'|'.e($b['gps_key']).'">'.e($b['reg_number']).'</option>';?></select></label><label>Crowding<select id="gc"><option>low</option><option>medium</option><option>high</option></select></label><button class="btn" type="button" onclick="gps(this)">Start sharing location</button> <span id="gs" class="muted"></span></div>
<script>function gps(b){const[v,k]=document.getElementById('gb').value.split('|');if(!navigator.geolocation)return;b.disabled=true;navigator.geolocation.watchPosition(p=>{const f=new FormData();f.append('bus',v);f.append('key',k);f.append('lat',p.coords.latitude);f.append('lng',p.coords.longitude);f.append('crowding',document.getElementById('gc').value);fetch('gps_update.php',{method:'POST',body:f});document.getElementById('gs').textContent='Sharing since '+new Date().toLocaleTimeString()},()=>{document.getElementById('gs').textContent='Location blocked';b.disabled=false},{enableHighAccuracy:true})}</script>
<h3>My trips</h3><?php foreach($trips as $t){echo '<div class="card trip"><span>'.e($t['from_city'].' to '.$t['to_city']).' · '.e($t['depart_date']).' '.substr($t['depart_time'],0,5).' <span class="pill '.$t['status'].'">'.$t['status'].'</span></span><form method="post">'.tok().'<input type="hidden" name="a" value="status"><input type="hidden" name="id" value="'.$t['id'].'">';foreach(['running','delayed','completed','cancelled'] as $s)echo '<button class="btn sm ghost" name="v" value="'.$s.'">'.$s.'</button> ';echo '</form></div>';}foot();
